float rnd(float x){
    return fract(sin(x + 10000.));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    float rad = .2;
    float px = cos(iTime * 2.) * rad;
    float py = sin(iTime) * rad;

    vec2 poi = vec2(px, py);
    poi = poi + .5;

    float dist = 1. - distance(uv, poi) * 3.;

    float res = 10. + rnd(floor(iTime)) * 20.;
    vec2 mskgrid = mod(uv, 1. / res) * res;
    float msk = clamp(step(mskgrid.x, .01) + step(mskgrid.y, .01), 0., 1.);

    float col = dist * msk;

    fragColor = vec4(vec3(col), 0.);
}
